'use strict';
const APP={view:'welcome',role:null,user:null,personnel:null,auth:{mode:'user',step:1,email:'',otp:'',devOtp:'',serial:'',password:'',trusted:false},camera:{stream:null,state:'idle',purpose:null,verification:'waiting',stable:0,scanTimer:null,scanLoop:null,detector:null,faceAvailable:false},registration:{step:1,data:{},photo:null,photoConfirmed:false,biometric:false,requestId:null},section:'dashboard',sidebar:false,requests:[],locations:[],conversations:[],contacts:[],activeConversation:null,messages:[],messageDraft:'',messagePoll:null,location:{enabled:false,watchId:null,last:null,sendBusy:false},notifications:[],refreshTimer:null};
const LEVELS=['PUBLIC','RESTRICTED','CONFIDENTIAL','SECRET','TOP SECRET'];
const DIVISIONS=['Pusat Kajian Ketahanan','Analisis Strategis','Riset Infrastruktur','Metodologi Intelijen','Komunikasi Strategis','Kesiapsiagaan Krisis','Kajian Geopolitik','Arsip Historis'];
const ROLES=['Mata-mata','Penyerbu','Logistik','Analis','Observasi'];
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function icon(n){const p={grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',people:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',search:'<circle cx="11" cy="11" r="6"/><path d="m16 16 4 4"/>',doc:'<path d="M6 2h9l5 5v15H6z"/><path d="M15 2v5h5M9 13h6M9 17h6"/>',map:'<path d="M4 6l6-3 4 3 6-3v15l-6 3-4-3-6 3zM10 3v15M14 6v15"/>',shield:'<path d="M12 3l8 3v5c0 5-3.2 8.8-8 11-4.8-2.2-8-6-8-11V6z"/><path d="m9 12 2 2 4-4"/>',lock:'<rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',logout:'<path d="M10 17l5-5-5-5M15 12H3M21 4v16"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',camera:'<path d="M4 8h3l2-3h6l2 3h3v11H4z"/><circle cx="12" cy="13" r="3.5"/>',upload:'<path d="M12 16V4M8 8l4-4 4 4M4 20h16"/>',check:'<path d="m5 12 4 4L19 6"/>',x:'<path d="m6 6 12 12M18 6 6 18"/>',refresh:'<path d="M20 11a8 8 0 0 0-14.9-4L3 10M3 5v5h5M4 13a8 8 0 0 0 14.9 4L21 14M21 19v-5h-5"/>',pin:'<path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2 2-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-2.8v-.2a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1-2-2 .1-.1a1.7 1.7 0 0 0 .3-1.9 1.7 1.7 0 0 0-.3-1.9 1.7 1.7 0 0 0-1.6-1H5.7v-2.8h.2a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9l-.1-.1 2-2 .1.1a1.7 1.7 0 0 0 1.9.3 1.7 1.7 0 0 0 1-1.6V5h2.8v.2a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1 2 2-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 0 0 0 1.6 1h.2v2.8h-.2a1.7 1.7 0 0 0-1.6 1z"/>',send:'<path d="m3 4 18 8-18 8 3-8zM6 12h15"/>',trash:'<path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7l1-3h4l1 3"/>'};return `<span class="icon"><svg viewBox="0 0 24 24">${p[n]||p.grid}</svg></span>`}
function logo(big=false){return `<svg ${big?'class="welcome-logo"':''} viewBox="0 0 120 120" xmlns="http://www.w3.org/2000/svg" aria-label="Lambang IKSN"><circle class="iksn-logo-ring" cx="60" cy="60" r="52" fill="none" stroke="#cbb99b" stroke-width="3"/><path d="M60 16 91 28v25c0 22-13 36-31 45-18-9-31-23-31-45V28z" fill="none" stroke="#e9e2d6" stroke-width="2.4"/><circle cx="60" cy="54" r="13" fill="none" stroke="#cbb99b" stroke-width="2"/><path d="m60 34 3.6 11.2H75l-10 6.9 3.8 11.1L60 56.4 51.2 63l3.8-11.1-10-6.9h11.4z" fill="#cbb99b"/><path d="M36 74c7 9 15 14 24 18M84 74c-7 9-15 14-24 18" fill="none" stroke="#e9e2d6" stroke-width="2"/><path d="M41 24c5 5 12 8 19 8M79 24c-5-5-12-8-19-8" fill="none" stroke="#8d6b43" stroke-width="2"/></svg>`}
function levelChip(v){const c=v==='TOP SECRET'?'danger':v==='SECRET'?'warning':v==='CONFIDENTIAL'?'info':v==='RESTRICTED'?'neutral':'success';return `<span class="chip ${c}">${esc(v)}</span>`}
function statusChip(v){const m={Active:'success',APPROVED:'success',SUCCESS:'success','TRUSTED DEVICE':'success',Operational:'success',PENDING:'warning','Pending Review':'warning','Under Review':'warning',REJECTED:'danger',Suspended:'danger',Revoked:'danger',Terminated:'danger',Archived:'neutral',STALE:'warning',OFFLINE:'neutral'};return `<span class="chip ${m[v]||'neutral'}">${esc(v)}</span>`}
function toast(msg,type='info'){const old=document.getElementById('iksnToast');if(old)old.remove();const el=document.createElement('div');el.id='iksnToast';el.style.cssText='position:fixed;left:50%;bottom:20px;transform:translateX(-50%);z-index:80;max-width:min(92vw,560px);padding:12px 14px;border:1px solid #3a3835;border-radius:12px;background:#111;color:#eee;font-size:12px;box-shadow:0 16px 50px rgba(0,0,0,.35);';el.innerHTML=esc(msg);document.body.appendChild(el);setTimeout(()=>el.remove(),3200)}
function openModal(title,body){document.getElementById('modalRoot').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="eyebrow">IKSN</div><h3 class="section-title" style="margin-top:5px">${esc(title)}</h3></div><button class="close-btn" onclick="closeModal()">${icon('x')}</button></div><div class="modal-body">${body}</div></div></div>`}
function closeModal(){document.getElementById('modalRoot').innerHTML=''}
async function api(url,opts={}){const o={credentials:'include',headers:{...(opts.body&&!((opts.body instanceof FormData))?{'Content-Type':'application/json'}:{}),...(opts.headers||{})},...opts};let res;try{res=await fetch(url,o)}catch(e){throw new Error('Tidak dapat terhubung ke server.')};let data={};try{data=await res.json()}catch{}if(!res.ok){if(res.status===401){APP.role=null;APP.user=null;APP.personnel=null;clearClientTimers();render();}throw new Error(data?.error?.message||'Permintaan gagal.')};return data}
function clearClientTimers(){if(APP.refreshTimer){clearInterval(APP.refreshTimer);APP.refreshTimer=null}if(APP.messagePoll){clearInterval(APP.messagePoll);APP.messagePoll=null}stopCamera();stopLocation();}
function setView(v){APP.view=v;APP.sidebar=false;render()}
function nav(s){APP.section=s;APP.view='app';APP.sidebar=false;render();if(s==='messages')loadMessagesHome();if(s==='locations')loadAdminLocations()}
function welcomeView(){return `<div class="welcome view"><div class="welcome-panel"><div class="brand" style="justify-content:center;margin-bottom:26px"><div class="brand-mark">${logo()}</div><div><div class="brand-name">IKSN</div><div class="brand-sub">Institute for Strategic Defense &amp; Resilience</div></div></div><div style="margin-bottom:18px">${logo(true)}</div><div class="eyebrow">Lingkungan Informasi Terbatas</div><div class="title">Institut Ketahanan Strategis Nusantara</div><div class="subtitle" style="margin:0 auto">Anda akan memasuki lingkungan informasi dengan tingkat akses terbatas. Sistem ini diperuntukkan bagi pengguna yang telah memperoleh otorisasi.</div><div style="margin-top:15px;font-size:11px;letter-spacing:.16em;font-weight:700">AUTHORIZED PERSONNEL ONLY</div><div class="muted" style="font-size:11px;line-height:1.6;max-width:560px;margin:12px auto 0">Seluruh aktivitas akses dapat dicatat dan diperiksa sesuai kebijakan keamanan institusi.</div><div class="welcome-actions"><button class="btn primary" onclick="startAuth()">${icon('lock')} ENTER SECURE ACCESS</button><button class="btn" onclick="setView('status')">${icon('search')} CEK STATUS PENGAJUAN</button><button class="mini-link" onclick="openInfo()">Informasi mengenai akses institusional</button></div><div class="welcome-meta"><div class="meta-cell"><span>System Status</span><strong>OPERATIONAL</strong></div><div class="meta-cell"><span>Classification</span><strong>RESTRICTED</strong></div><div class="meta-cell"><span>Access Policy</span><strong>ENFORCED</strong></div></div></div><button class="corner-admin admin-portal-trigger" onclick="setView('adminLogin')"><span class="admin-portal-mark">${icon('shield')}</span><span><b>ADMIN PORTAL</b><small>PRIVILEGED ACCESS</small></span></button></div>`}
function openInfo(){openModal('Informasi mengenai akses institusional',`<div class="stack"><div class="notice">IKSN adalah institusi fiktif untuk demonstrasi antarmuka. Tidak mewakili organisasi atau sistem pemerintah yang sebenarnya.</div><p class="muted" style="line-height:1.7">Akses diberikan melalui proses administrasi. Kamera digunakan sebagai verifikasi kehadiran wajah pada prototype; lokasi hanya dikirim ketika personel mengaktifkan fitur berbagi lokasi.</p><div class="rule"></div><div class="notice">Prototype ini bukan sistem biometrik atau keamanan militer produksi. Untuk deployment nyata, gunakan identity provider, OTP provider, PostgreSQL, object storage, dan kontrol keamanan yang sesuai.</div></div>`)}
function startAuth(){APP.auth.mode='user';APP.auth.step=1;APP.auth.email='';APP.auth.devOtp='';APP.auth.trusted=false;setView('auth')}
function authHeader(t,s){return `<div class="auth-header"><div class="eyebrow">${APP.auth.mode==='admin'?'PRIVILEGED ACCESS':'SECURE ACCESS'}</div><h1 class="title" style="font-size:38px">${esc(t)}</h1><div class="subtitle">${esc(s)}</div></div>`}
function authStepper(){const names=['Identitas','OTP','Kredensial','Perangkat','Biometrik','Clearance'];return `<div class="stepper">${names.map((n,i)=>`<div class="step ${APP.auth.step===i+1?'active':''} ${APP.auth.step>i+1?'done':''}"><span class="n">${APP.auth.step>i+1?'✓':i+1}</span>${n}</div>`).join('')}</div>`}
function authView(){return `<div class="auth-shell view"><aside class="auth-aside"><div><div class="brand">${logo()}<div><div class="brand-name">INSTITUT KETAHANAN STRATEGIS NUSANTARA</div><div class="brand-sub">Institute for Strategic Defense &amp; Resilience</div></div></div><div style="margin-top:42px"><div class="eyebrow">Confidentiality Notice</div><p class="muted" style="line-height:1.7;font-size:12px">Sistem ini berisi informasi terbatas yang hanya dapat diakses oleh pengguna terotorisasi. Akses, penggunaan, atau penyebaran tanpa kewenangan tidak diperbolehkan.</p></div></div><div class="muted" style="font-size:10px;line-height:1.6">PROTOTYPE ENVIRONMENT — ALL RECORDS ARE FICTIONAL</div></aside><main class="auth-main"><div class="auth-box"><div class="auth-top"><button class="mini-link" onclick="setView('welcome')">← Kembali</button>${authStepper()}</div>${authBody()}</div></main></div>`}
function authBody(){if(APP.auth.mode==='admin')return adminAuthBody();if(APP.auth.step===1)return userIdentity();if(APP.auth.step===2)return userOtp();if(APP.auth.step===3)return userCredential();if(APP.auth.step===4)return deviceStep('user');if(APP.auth.step===5)return faceStep('user');return clearanceStep()}
function userIdentity(){return `${authHeader('Secure Access','Masukkan email institusi lalu minta OTP verifikasi.') }<div class="card"><div class="field"><label class="label">Email Institusi</label><input class="input" id="loginEmail" type="email" autocomplete="email" value="${esc(APP.auth.email)}" placeholder="nama@institusi.example"></div><button class="btn primary block" onclick="requestUserOtp()">KIRIM OTP</button><div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-top:10px"><button class="mini-link" onclick="setView('status')">Cek Status Pengajuan</button><button class="mini-link" onclick="setView('register')">Ajukan Akses Institusional</button></div></div>`}
async function requestUserOtp(){const email=(document.getElementById('loginEmail')?.value||'').trim().toLowerCase();if(!/^\S+@\S+\.\S+$/.test(email))return toast('Masukkan email yang valid.','danger');try{const r=await api('/api/auth/personnel/request-otp',{method:'POST',body:JSON.stringify({email})});APP.auth.email=email;APP.auth.step=2;APP.auth.devOtp=r.data.devOtp||'';render()}catch(e){toast(e.message,'danger')}}
function userOtp(){return `${authHeader('One-Time Verification','Masukkan kode OTP enam digit yang diterbitkan untuk akun personel ini.')}<div class="card"><div class="field"><label class="label">Kode OTP</label><div class="otp">${Array.from({length:6},(_,i)=>`<input maxlength="1" inputmode="numeric" id="uotp${i}" ${i===0?'autofocus':''}>`).join('')}</div>${APP.auth.devOtp?`<div class="dev-otp">OTP DEVELOPMENT UNTUK TEST: <b>${esc(APP.auth.devOtp)}</b></div>`:''}</div><button class="btn primary block" onclick="verifyUserOtp()">VERIFIKASI OTP</button><button class="mini-link" style="width:100%;margin-top:7px" onclick="APP.auth.step=1;render()">Ganti email</button></div>`}
async function verifyUserOtp(){const otp=Array.from({length:6},(_,i)=>document.getElementById('uotp'+i)?.value||'').join('');try{const r=await api('/api/auth/personnel/verify-otp',{method:'POST',body:JSON.stringify({email:APP.auth.email,otp})});APP.role='PERSONNEL';APP.user=r.data.user;APP.auth.step=3;APP.auth.devOtp='';render()}catch(e){toast(e.message,'danger')}}
function userCredential(){return `${authHeader('Credential Verification','Masukkan Serial Number dan kata sandi akun personel.')}<div class="card"><div class="field"><label class="label">Serial Number</label><input class="input" id="serial" placeholder="IKSN-SN-XXXX-XXXX"></div><div class="field"><label class="label">Kata Sandi</label><input class="input" id="credPass" type="password" placeholder="Kata sandi"></div><div class="field inline"><input class="check" id="trust" type="checkbox"><label for="trust" style="font-size:12px">Percayai perangkat ini</label></div><button class="btn primary block" onclick="verifyUserCredential()">LANJUTKAN</button></div>`}
async function verifyUserCredential(){const serial=document.getElementById('serial')?.value.trim();const password=document.getElementById('credPass')?.value||'';try{await api('/api/auth/personnel/verify-credentials',{method:'POST',body:JSON.stringify({serial,password})});APP.auth.trusted=document.getElementById('trust')?.checked;APP.auth.step=4;render()}catch(e){toast(e.message,'danger')}}
function adminLogin(){APP.auth.mode='admin';APP.auth.step=1;APP.auth.email='';APP.auth.devOtp='';setView('adminLogin')}
function adminAuthBody(){if(APP.auth.step===1)return `${authHeader('Administrator Gate','Gunakan kredensial administrator yang dikonfigurasi di server.')}<div class="card admin-security-card"><div class="field"><label class="label">Email Administrator</label><input class="input" id="adminEmail" type="email" placeholder="admin@domain.example"></div><div class="field"><label class="label">Password Administrator</label><input class="input" id="adminPassword" type="password" placeholder="Masukkan password"></div><button class="btn primary block" onclick="requestAdminOtp()">VERIFIKASI KREDENSIAL</button></div>`;if(APP.auth.step===2)return `${authHeader('Administrator OTP','Masukkan OTP enam digit yang diterbitkan oleh server administrator.')}<div class="card admin-security-card"><div class="field"><label class="label">Kode OTP</label><div class="admin-auth-code">${Array.from({length:6},(_,i)=>`<input maxlength="1" inputmode="numeric" id="aotp${i}" ${i===0?'autofocus':''}>`).join('')}</div>${APP.auth.devOtp?`<div class="dev-otp">OTP DEVELOPMENT UNTUK TEST: <b>${esc(APP.auth.devOtp)}</b></div>`:''}</div><button class="btn primary block" onclick="verifyAdminOtp()">VERIFIKASI OTP</button><div class="admin-auth-note" style="margin-top:12px">Pada production, OTP dikirim melalui provider autentikasi dan tidak ditampilkan pada UI.</div></div>`;if(APP.auth.step===3)return deviceStep('admin');if(APP.auth.step===4)return faceStep('admin');return `<div>${authHeader('Privileged Access Confirmed','Kredensial, OTP, perangkat, dan verifikasi kamera telah dilalui.')}<div class="card"><div class="eyebrow">ADMINISTRATOR</div><h3 style="margin:8px 0">${esc(APP.user?.name||'IKSN Administrator')}</h3><div class="notice success">Sesi administrator aktif.</div><button class="btn primary block" style="margin-top:14px" onclick="APP.view='app';APP.section='dashboard';startRefresh();render()">ENTER ADMIN CONSOLE</button></div></div>`;}
async function requestAdminOtp(){const email=(document.getElementById('adminEmail')?.value||'').trim().toLowerCase();const password=document.getElementById('adminPassword')?.value||'';try{const r=await api('/api/auth/admin/request-otp',{method:'POST',body:JSON.stringify({email,password})});APP.auth.email=email;APP.auth.step=2;APP.auth.devOtp=r.data.devOtp||'';render()}catch(e){toast(e.message,'danger')}}
async function verifyAdminOtp(){const otp=Array.from({length:6},(_,i)=>document.getElementById('aotp'+i)?.value||'').join('');try{const r=await api('/api/auth/admin/verify-otp',{method:'POST',body:JSON.stringify({email:APP.auth.email,otp})});APP.role='ADMIN';APP.user=r.data.user;APP.auth.devOtp='';APP.auth.step=3;render()}catch(e){toast(e.message,'danger')}}
function deviceStep(kind){return `${authHeader('Trusted Device Check','Pemeriksaan perangkat ringan sebelum tahap verifikasi wajah.')}<div class="device-check"><div class="card"><div class="eyebrow">Perangkat</div><h3 style="margin:8px 0">${/Android/i.test(navigator.userAgent)?'Perangkat Android':/iPhone|iPad/i.test(navigator.userAgent)?'Perangkat iOS':'Workstation'}</h3><div class="status-list"><div class="status-row"><span>Browser</span><b>${/Chrome/i.test(navigator.userAgent)?'Chrome':/Safari/i.test(navigator.userAgent)?'Safari':'Modern Browser'}</b></div><div class="status-row"><span>Status</span><b>${statusChip('TRUSTED DEVICE')}</b></div></div></div><div class="card"><div class="eyebrow">Keputusan</div><h3 style="margin:8px 0">Perangkat Terverifikasi</h3><p class="muted" style="font-size:12px;line-height:1.6">Tidak ada pengenal perangkat sensitif yang ditampilkan pada UI.</p><button class="btn primary block" onclick="APP.auth.step=5;render()">LANJUTKAN</button></div></div>`}
function faceStep(purpose){return `${authHeader('Verifikasi Wajah','Akses kamera nyata digunakan. Verifikasi prototype hanya dinyatakan selesai setelah kondisi yang jelas terpenuhi.')}<div class="card"><div id="cameraArea">${cameraUI()}</div></div><div class="notice" style="margin-top:12px">Jangan menganggap proses berhasil hanya karena timer selesai. Kamera harus aktif dan wajah harus terdeteksi (atau fallback manual prototype diaktifkan bila face detection browser tidak tersedia).</div>`}
function cameraUI(){if(APP.camera.state==='requesting')return `<div class="camera-wrap"><div class="camera-placeholder"><div><div class="eyebrow">Meminta Akses Kamera</div><p class="muted" style="font-size:12px">Silakan izinkan kamera pada browser.</p></div></div></div>`;if(APP.camera.state==='error'||APP.camera.state==='insecure'){return `<div class="notice danger"><b>${APP.camera.state==='insecure'?'KONEKSI AMAN DIPERLUKAN':'KAMERA TIDAK DAPAT DIGUNAKAN'}</b><p>${esc(APP.camera.error||'Browser tidak memberikan akses kamera.')}</p><button class="btn small" onclick="startCamera('${APP.camera.purpose||'user'}')">COBA LAGI</button></div>`}if(APP.camera.state==='active'){const det=APP.camera.verification==='detected'||APP.camera.verification==='processing'||APP.camera.verification==='done';return `<div class="camera-wrap"><video id="camVideo" autoplay playsinline muted></video><div class="face-frame ${det?'detected':''}"></div><div class="camera-state"><span class="chip success">KAMERA AKTIF</span><span class="chip neutral">REAL CAMERA</span></div><div class="camera-bottom"><div class="camera-hud"><b>VERIFIKASI WAJAH</b><br><span class="muted">${APP.camera.verification==='waiting'?'Menunggu wajah di dalam frame':APP.camera.verification==='detected'?'Wajah terdeteksi — pertahankan posisi':APP.camera.verification==='processing'?'Verifikasi prototype berlangsung':'Verifikasi selesai'}</span></div><button class="btn small" onclick="stopCamera();render()">HENTIKAN KAMERA</button></div></div>${verificationPanel()}`}return `<div class="camera-placeholder"><div><div style="width:62px;height:62px;border:1px solid #3b3935;border-radius:18px;display:grid;place-items:center;margin:0 auto 16px">${icon('camera')}</div><div class="eyebrow">Verifikasi Wajah</div><h3 style="margin:7px 0">Kamera Diperlukan</h3><p class="muted" style="font-size:12px;line-height:1.6;max-width:500px;margin:0 auto 18px">Preview kamera akan muncul di dalam kotak setelah Anda memberi izin.</p><button class="btn primary" onclick="startCamera('${APP.camera.purpose||'user'}')">${icon('camera')} BUKA KAMERA</button></div></div>`}
function verificationPanel(){const v=APP.camera.verification;const native=APP.camera.faceAvailable;return `<div class="verify-list"><div class="verify-item ${v!=='waiting'?'ok':'wait'}"><span><i class="live-dot"></i>Wajah terdeteksi</span><b>${v==='waiting'?'MENUNGGU':v==='detected'||v==='processing'||v==='done'?'OK':'MENUNGGU'}</b></div><div class="verify-item ${v==='processing'||v==='done'?'ok':'wait'}"><span>Posisi wajah sesuai</span><b>${v==='processing'||v==='done'?'OK':'MENUNGGU'}</b></div><div class="verify-item ${v==='processing'||v==='done'?'ok':'wait'}"><span>Pemeriksaan prototype</span><b>${v==='processing'||v==='done'?'BERJALAN':'MENUNGGU'}</b></div><div class="verify-item ${v==='done'?'ok':'wait'}"><span>Status</span><b>${v==='done'?'TERKONFIRMASI':'MENUNGGU'}</b></div>${v==='done'?`<button class="btn primary block" onclick="finishFace()">LANJUTKAN</button>`:''}<div class="help">${native?'Face detector browser aktif.':'Face detector browser tidak tersedia; sistem memakai fallback visual prototype. Tidak ada klaim pengenalan identitas produksi.'}</div>${!native&&v==='waiting'?`<button class="btn block" style="margin-top:8px" onclick="manualPrototypeFaceCheck()">KONFIRMASI MANUAL PROTOTYPE</button>`:''}</div>`}
async function startCamera(purpose){stopCamera();APP.camera.purpose=purpose;APP.camera.state='requesting';APP.camera.verification='waiting';render();if(!window.isSecureContext&&!['localhost','127.0.0.1'].includes(location.hostname)){APP.camera.state='insecure';APP.camera.error='Gunakan HTTPS atau localhost agar kamera browser dapat digunakan.';render();return}if(!navigator.mediaDevices?.getUserMedia){APP.camera.state='error';APP.camera.error='Browser tidak menyediakan getUserMedia.';render();return}try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'user'},width:{ideal:720},height:{ideal:540}},audio:false});APP.camera.stream=s;APP.camera.state='active';APP.camera.error=null;render();setTimeout(async()=>{const v=document.getElementById('camVideo');if(!v)return;v.srcObject=s;try{await v.play()}catch{}initFaceDetection(v)},60)}catch(e){APP.camera.state='error';APP.camera.error=({'NotAllowedError':'Izin kamera ditolak. Izinkan kamera pada pengaturan situs.','NotFoundError':'Tidak ada kamera yang terdeteksi.','NotReadableError':'Kamera sedang digunakan aplikasi lain.','OverconstrainedError':'Konfigurasi kamera tidak tersedia.','SecurityError':'Akses kamera diblokir kebijakan keamanan.'}[e.name]||'Kamera tidak dapat digunakan.');render()}}
async function initFaceDetection(video){APP.camera.faceAvailable=false;APP.camera.stable=0;APP.camera.detector=null;try{if('FaceDetector' in window){APP.camera.detector=new FaceDetector({fastMode:true,maxDetectedFaces:1});APP.camera.faceAvailable=true;}}catch{}scanFace(video)}
function scanFace(video){stopScanOnly();const loop=async()=>{if(APP.camera.state!=='active'||!APP.camera.stream)return;let detected=false;if(video.readyState>=2){try{if(APP.camera.detector){const fs=await APP.camera.detector.detect(video);detected=fs.length>0;}else{detected=fallbackFacePresence(video)}}catch{detected=false}}APP.camera.stable=detected?Math.min(APP.camera.stable+1,80):0;if(APP.camera.stable>=12&&APP.camera.verification==='waiting'){APP.camera.verification='detected';render();APP.camera.scanTimer=setTimeout(()=>beginFaceProcessing(),900);return}APP.camera.scanLoop=requestAnimationFrame(loop)};APP.camera.scanLoop=requestAnimationFrame(loop)}
function fallbackFacePresence(video){const c=document.createElement('canvas');c.width=96;c.height=72;const x=c.getContext('2d',{willReadFrequently:true});if(!x)return false;x.drawImage(video,0,0,96,72);const d=x.getImageData(25,10,46,52).data;let skin=0,bright=0,total=d.length/4;for(let i=0;i<d.length;i+=4){const r=d[i],g=d[i+1],b=d[i+2];if(r>80&&g>45&&b>25&&r>g*1.03&&g>b*1.03)skin++;if((r+g+b)/3>55)bright++;}return skin/total>.14&&bright/total>.56}
function beginFaceProcessing(){if(APP.camera.state!=='active'||APP.camera.verification!=='detected')return;stopScanOnly();APP.camera.verification='processing';render();APP.camera.scanTimer=setTimeout(()=>{if(APP.camera.state==='active'&&APP.camera.verification==='processing'){APP.camera.verification='done';render()}},1600)}
function manualPrototypeFaceCheck(){if(APP.camera.state!=='active'){toast('Buka kamera terlebih dahulu.','danger');return}APP.camera.verification='processing';render();setTimeout(()=>{if(APP.camera.state==='active'&&APP.camera.verification==='processing'){APP.camera.verification='done';render()}},1600)}
function stopScanOnly(){if(APP.camera.scanLoop){cancelAnimationFrame(APP.camera.scanLoop);APP.camera.scanLoop=null}if(APP.camera.scanTimer){clearTimeout(APP.camera.scanTimer);APP.camera.scanTimer=null}}
function stopCamera(){stopScanOnly();if(APP.camera.stream){APP.camera.stream.getTracks().forEach(t=>t.stop());APP.camera.stream=null}APP.camera.state='idle';APP.camera.verification='waiting'}
function finishFace(){if(APP.camera.verification!=='done')return toast('Verifikasi wajah belum selesai.','danger');const purpose=APP.camera.purpose;stopCamera();if(purpose==='registration'){APP.registration.biometric=true;APP.registration.step=5;APP.view='register';render();return}if(purpose==='admin'){APP.auth.step=5;render();return}APP.auth.step=6;render()}
function clearanceStep(){return `<div>${authHeader('Clearance Confirmed','Otorisasi sesi berhasil diverifikasi.') }<div class="card"><div class="detail-head"><div class="detail-photo">${APP.personnel?.photo?`<img src="${APP.personnel.photo}" alt="Foto profil">`:''}</div><div><div class="eyebrow">Authorized Personnel</div><h3 style="margin:7px 0">${esc(APP.personnel?.name||APP.user?.email||'Personel')}</h3><div class="muted" style="font-size:12px">${esc(APP.personnel?.id||APP.user?.personnelId||'—')} · ${esc(APP.personnel?.position||'Personel')}</div></div></div><div class="rule"></div><div class="grid grid-3"><div class="stat"><div class="k">Clearance</div><div class="v" style="font-size:18px">${esc(APP.personnel?.clearance||'RESTRICTED')}</div></div><div class="stat"><div class="k">Device</div><div class="v" style="font-size:18px">VERIFIED</div></div><div class="stat"><div class="k">Session</div><div class="v" style="font-size:18px">SECURE</div></div></div><button class="btn primary block" onclick="enterApp()">ENTER ARCHIVE</button></div></div>`}
async function enterApp(){try{const r=await api('/api/personnel/me');APP.personnel=r.data.personnel;APP.view='app';APP.section='dashboard';startRefresh();render();}catch(e){toast(e.message,'danger')}}
function statusView(){return `<div class="auth-shell view"><aside class="auth-aside"><div>${logo()}<div class="eyebrow" style="margin-top:26px">Request Status</div><h2 style="font-size:28px;line-height:1.15">Periksa status pengajuan.</h2><p class="muted" style="font-size:12px;line-height:1.7">Gunakan email yang sama dengan pengajuan akses Anda.</p></div><div class="muted" style="font-size:10px">FICTIONAL INSTITUTIONAL PROTOTYPE</div></aside><main class="auth-main"><div class="auth-box"><div class="auth-top"><button class="mini-link" onclick="setView('welcome')">← Kembali</button><div class="eyebrow">STATUS PENGAJUAN</div></div><div class="card"><div class="field"><label class="label">Email Pengajuan</label><input class="input" id="statusEmail" type="email" placeholder="nama@email.com"></div><button class="btn primary block" onclick="loadRequestStatus()">CEK STATUS</button></div><div id="statusResult" style="margin-top:14px"></div></div></main></div>`}
async function loadRequestStatus(){const email=(document.getElementById('statusEmail')?.value||'').trim().toLowerCase();if(!email)return toast('Masukkan email pengajuan.','danger');try{const r=await api('/api/requests/status?email='+encodeURIComponent(email));const items=r.data.requests;document.getElementById('statusResult').innerHTML=items.length?items.map(x=>`<div class="card" style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><div><div class="eyebrow">${esc(x.id)}</div><h3 style="margin:7px 0;font-size:15px">${esc(x.name)}</h3><div class="muted" style="font-size:11px">${esc(x.submitted||'')}</div></div>${statusChip(x.status)}</div><div class="rule"></div><div class="grid grid-2"><div class="meta-box"><div class="k">Institusi</div><div class="v">${esc(x.institution)}</div></div><div class="meta-box"><div class="k">Clearance</div><div class="v">${esc(x.clearance)}</div></div></div>${x.status==='APPROVED'?`<div class="notice success" style="margin-top:12px">Akses disetujui.</div>${x.serial||x.loginPassword?`<div class="dev-otp" style="margin-top:10px">CREDENTIAL DEVELOPMENT: Serial <b>${esc(x.serial||'—')}</b> · Password <b>${esc(x.loginPassword||'—')}</b></div>`:''}`:''}</div>`).join(''):`<div class="notice">Belum ada pengajuan untuk email tersebut.</div>`}catch(e){toast(e.message,'danger')}}
function registerView(){return `<div class="auth-shell view"><aside class="auth-aside"><div>${logo()}<div class="eyebrow" style="margin-top:26px">Request Institutional Access</div><h2 style="font-size:28px;line-height:1.15">Pengajuan akses, bukan pendaftaran publik.</h2><p class="muted" style="font-size:12px;line-height:1.7">Akun dibuat setelah pemeriksaan administratif dan penetapan clearance oleh administrator berwenang.</p></div><div class="muted" style="font-size:10px">SERVER-BACKED REQUEST FLOW</div></aside><main class="auth-main"><div class="auth-box"><div class="auth-top"><button class="mini-link" onclick="setView('welcome')">← Kembali</button><div class="eyebrow">Akses Institusional</div></div>${registrationStepper()}${registrationBody()}</div></main></div>`}
function registrationStepper(){const n=['Data Diri','Profil Institusi','Foto Identitas','Verifikasi Wajah','Permintaan Akses','Konfirmasi'];return `<div class="stepper" style="margin-bottom:18px">${n.map((x,i)=>`<div class="step ${APP.registration.step===i+1?'active':''} ${APP.registration.step>i+1?'done':''}"><span class="n">${APP.registration.step>i+1?'✓':i+1}</span>${x}</div>`).join('')}</div>`}
function registrationBody(){switch(APP.registration.step){case 1:return regPersonal();case 2:return regInstitution();case 3:return regPhoto();case 4:return regBio();case 5:return regAccess();default:return regConfirm()}}
function regPersonal(){const d=APP.registration.data;return `<div class="auth-header"><div class="eyebrow">01 DATA DIRI</div><h1 class="title" style="font-size:34px">Identitas Pribadi</h1><div class="subtitle">Isi data identitas dasar.</div></div><div class="card grid grid-2"><div class="field"><label class="label">Nama Lengkap *</label><input class="input" id="rName" value="${esc(d.name)}"></div><div class="field"><label class="label">Nama Panggilan</label><input class="input" id="rNick" value="${esc(d.nick)}"></div><div class="field"><label class="label">Tanggal Lahir *</label><input class="input" id="rDob" type="date" value="${esc(d.dob)}"></div><div class="field"><label class="label">Negara *</label><input class="input" id="rCountry" value="${esc(d.country||'Indonesia')}"></div><div class="field"><label class="label">Provinsi *</label><input class="input" id="rProvince" value="${esc(d.province)}"></div><div class="field"><label class="label">Kota *</label><input class="input" id="rCity" value="${esc(d.city)}"></div><div class="field"><label class="label">Nomor Telepon *</label><input class="input" id="rPhone" type="tel" value="${esc(d.phone)}"></div><div class="field"><label class="label">Email Utama *</label><input class="input" id="rEmail" type="email" value="${esc(d.email)}"></div><div class="field"><label class="label">Email Alternatif</label><input class="input" id="rAlt" type="email" value="${esc(d.alt)}"></div><div style="grid-column:1/-1"><button class="btn primary block" onclick="saveRegPersonal()">LANJUTKAN</button></div></div>`}
function saveRegPersonal(){const g=id=>(document.getElementById(id)?.value||'').trim();const d={name:g('rName'),nick:g('rNick'),dob:g('rDob'),country:g('rCountry'),province:g('rProvince'),city:g('rCity'),phone:g('rPhone'),email:g('rEmail').toLowerCase(),alt:g('rAlt').toLowerCase()};const req=['name','dob','country','province','city','phone','email'];if(req.some(k=>!d[k]))return toast('Lengkapi semua kolom wajib.','danger');if(!/^\S+@\S+\.\S+$/.test(d.email))return toast('Email utama tidak valid.','danger');APP.registration.data={...APP.registration.data,...d};APP.registration.step=2;render()}
function regInstitution(){const d=APP.registration.data;return `<div class="auth-header"><div class="eyebrow">02 PROFIL INSTITUSI</div><h1 class="title" style="font-size:34px">Profil Institusional</h1><div class="subtitle">Informasi organisasi membantu administrator memahami tujuan dan lingkup akses.</div></div><div class="card grid grid-2"><div class="field"><label class="label">Personnel ID</label><input class="input" value="DIBERIKAN SAAT DISETUJUI" disabled></div><div class="field"><label class="label">Institusi / Organisasi *</label><input class="input" id="rInst" value="${esc(d.inst)}"></div><div class="field"><label class="label">Divisi *</label><input class="input" id="rDiv" value="${esc(d.div)}"></div><div class="field"><label class="label">Jabatan *</label><input class="input" id="rPos" value="${esc(d.pos)}"></div><div class="field"><label class="label">Bidang Keahlian *</label><select class="select" id="rExpert">${['Ketahanan Infrastruktur','Kesiapsiagaan Krisis','Metodologi Analisis','Geopolitik','Komunikasi Strategis','Resiliensi Maritim','Sejarah Strategis','Keamanan Humaniter'].map(x=>`<option ${d.expert===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label class="label">Tujuan Penggunaan Sistem *</label><input class="input" id="rPurpose" value="${esc(d.purpose)}"></div><div style="grid-column:1/-1;display:flex;gap:8px"><button class="btn" onclick="APP.registration.step=1;render()">KEMBALI</button><button class="btn primary" style="flex:1" onclick="saveRegInstitution()">LANJUTKAN</button></div></div>`}
function saveRegInstitution(){const d={inst:document.getElementById('rInst').value.trim(),div:document.getElementById('rDiv').value.trim(),pos:document.getElementById('rPos').value.trim(),expert:document.getElementById('rExpert').value,purpose:document.getElementById('rPurpose').value.trim()};if(Object.values(d).some(v=>!v))return toast('Lengkapi profil institusional wajib.','danger');APP.registration.data={...APP.registration.data,...d};APP.registration.step=3;render()}
function regPhoto(){return `<div class="auth-header"><div class="eyebrow">03 FOTO IDENTITAS</div><h1 class="title" style="font-size:34px">Tambahkan Foto Profil</h1><div class="subtitle">Foto menjadi bagian dari profil identitas internal.</div></div><div class="card"><div class="photo-uploader"><div class="photo-preview" id="regPhotoPreview">${APP.registration.photo?`<img src="${APP.registration.photo}" alt="Pratinjau foto">`:'Belum ada foto'}</div><div><div class="notice">Gunakan foto depan dengan wajah terlihat jelas, pencahayaan wajar, tanpa filter ekstrem.</div><div class="upload-actions" style="margin-top:12px"><input id="photoFile" type="file" accept="image/jpeg,image/png,image/webp" class="hidden" onchange="handlePhotoFile(event)"><button class="btn" onclick="document.getElementById('photoFile').click()">${icon('upload')} UPLOAD FOTO</button><button class="btn" onclick="startRegistrationCapture()">${icon('camera')} AMBIL FOTO DENGAN KAMERA</button></div></div></div><div style="display:flex;gap:8px;margin-top:18px"><button class="btn" onclick="APP.registration.step=2;render()">KEMBALI</button><button class="btn primary" style="flex:1" onclick="confirmRegPhoto()" ${APP.registration.photo?'':'disabled'}>KONFIRMASI FOTO</button></div></div>`}
function handlePhotoFile(e){const f=e.target.files?.[0];if(!f)return;if(!/^image\/(jpeg|png|webp)$/.test(f.type)||f.size>5*1024*1024)return toast('Gunakan JPG/PNG/WEBP maksimal 5 MB.','danger');const fr=new FileReader();fr.onload=()=>{APP.registration.photo=fr.result;APP.registration.photoConfirmed=false;render()};fr.readAsDataURL(f)}
function confirmRegPhoto(){if(!APP.registration.photo)return toast('Tambahkan foto terlebih dahulu.','danger');APP.registration.photoConfirmed=true;APP.registration.step=4;render()}
async function startRegistrationCapture(){APP.camera.purpose='registration';if(!window.isSecureContext&&!['localhost','127.0.0.1'].includes(location.hostname))return toast('Kamera memerlukan HTTPS atau localhost.','danger');try{const s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});openModal('Ambil Foto Dengan Kamera',`<div class="camera-wrap"><video id="regVideo" autoplay playsinline muted></video><div class="face-frame"></div></div><div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap"><button class="btn primary" onclick="captureRegPhoto()">AMBIL FOTO</button><button class="btn" onclick="closeRegCamera()">TUTUP KAMERA</button></div>`);setTimeout(async()=>{const v=document.getElementById('regVideo');if(v){v.srcObject=s;v.muted=true;await v.play().catch(()=>{});window._regStream=s}},50)}catch(e){toast(e.message||'Kamera tidak dapat digunakan.','danger')}}
function captureRegPhoto(){const v=document.getElementById('regVideo');if(!v||!window._regStream)return;const c=document.createElement('canvas');c.width=v.videoWidth||720;c.height=v.videoHeight||540;c.getContext('2d').drawImage(v,0,0,c.width,c.height);APP.registration.photo=c.toDataURL('image/jpeg',.85);APP.registration.photoConfirmed=false;closeRegCamera();render()}
function closeRegCamera(){if(window._regStream){window._regStream.getTracks().forEach(t=>t.stop());window._regStream=null}closeModal()}
function regBio(){return `<div class="auth-header"><div class="eyebrow">04 VERIFIKASI WAJAH</div><h1 class="title" style="font-size:34px">Verifikasi Identitas</h1><div class="subtitle">Gunakan kamera nyata. Jangan ada status sukses sebelum pemeriksaan selesai.</div></div><div class="card">${APP.registration.biometric?`<div class="notice success"><b>VERIFIKASI WAJAH SELESAI</b><p>Kamera telah dihentikan.</p></div><button class="btn primary block" onclick="APP.registration.step=5;render()">LANJUTKAN</button>`:`<div class="notice">Foto profil telah dikonfirmasi. Buka kamera dan tunggu sampai kondisi verifikasi terpenuhi.</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px"><button class="btn primary" onclick="startCamera('registration')">BUKA KAMERA</button><button class="btn" onclick="APP.registration.step=3;render()">GANTI FOTO</button></div>`}</div>`}
function regAccess(){return `<div class="auth-header"><div class="eyebrow">05 PERMINTAAN AKSES</div><h1 class="title" style="font-size:34px">Ruang Lingkup Akses</h1><div class="subtitle">Pilih clearance yang diajukan dan setujui kebijakan lokasi opsional.</div></div><div class="card"><div class="field"><label class="label">Requested Clearance</label><select class="select" id="reqClearance">${LEVELS.map(x=>`<option ${APP.registration.data.clearanceRequested===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="location-consent"><div><b style="font-size:12px">Berbagi lokasi</b><div class="help">Opsional. Lokasi hanya dikirim jika Anda mengaktifkannya setelah akun aktif.</div></div><label class="switch"><input id="reqLoc" type="checkbox" ${APP.registration.data.locationConsent?'checked':''}><span class="slider"></span></label></div><div style="display:flex;gap:8px;margin-top:18px"><button class="btn" onclick="APP.registration.step=4;render()">KEMBALI</button><button class="btn primary" style="flex:1" onclick="submitAccessRequest()">KIRIM PENGAJUAN</button></div></div>`}
async function submitAccessRequest(){APP.registration.data.clearanceRequested=document.getElementById('reqClearance').value;APP.registration.data.locationConsent=document.getElementById('reqLoc').checked;try{const r=await api('/api/requests',{method:'POST',body:JSON.stringify({data:{...APP.registration.data,photo:APP.registration.photo,photoConfirmed:APP.registration.photoConfirmed,biometricVerified:APP.registration.biometric}})});APP.registration.requestId=r.data.request.id;APP.registration.step=6;render()}catch(e){toast(e.message,'danger')}}
function regConfirm(){return `<div class="auth-header"><div class="eyebrow">06 KONFIRMASI</div><h1 class="title" style="font-size:34px">Pengajuan Terkirim</h1><div class="subtitle">Simpan ID pengajuan untuk pemeriksaan status.</div></div><div class="card"><div class="notice success"><b>${esc(APP.registration.requestId||'REQ-—')}</b><p>Pengajuan telah diterima server dan menunggu pemeriksaan administrator.</p></div><div class="rule"></div><button class="btn primary block" onclick="setView('status')">CEK STATUS PENGAJUAN</button><button class="mini-link" style="width:100%;margin-top:8px" onclick="setView('welcome')">Kembali ke beranda</button></div>`}
function adminView(){return appShell('admin')}
function personnelView(){return appShell('personnel')}
function appShell(){const isAdmin=APP.role==='ADMIN';return `<div class="shell view"><aside class="sidebar ${APP.sidebar?'open':''}"><div class="brand">${logo()}<div><div class="brand-name">IKSN</div><div class="brand-sub">Secure Information Archive</div></div></div><nav class="side-nav">${isAdmin?adminNav():personnelNav()}</nav><div class="sidebar-footer">FICTIONAL INSTITUTIONAL PROTOTYPE<br>HAYDAR-S/01 · ${isAdmin?'PRIVILEGED':'PERSONNEL'} ACCESS</div></aside><main class="main"><header class="topbar"><button class="mobile-menu" onclick="APP.sidebar=!APP.sidebar;render()">${icon('menu')}</button><div class="brand"><div class="brand-mark" style="width:32px;height:32px">${logo()}</div><div><div class="brand-name">${isAdmin?'ADMIN CONSOLE':'PERSONNEL CONSOLE'}</div><div class="brand-sub">${isAdmin?'PRIVILEGED ACCESS':'AUTHORIZED ACCESS'}</div></div></div><div class="top-actions"><button class="btn small top-hide" onclick="nav('notifications')">${icon('bell')}</button><div class="profile-mini"><div class="avatar">${APP.personnel?.photo?`<img src="${APP.personnel.photo}" alt="">`:esc((APP.user?.name||'A').slice(0,1))}</div><div class="small-meta"><div style="font-size:11px;font-weight:700">${esc(isAdmin?APP.user?.name:APP.personnel?.name||APP.user?.email)}</div><div style="font-size:9px;color:#777">${esc(isAdmin?'ADMIN':APP.personnel?.id||'PERSONNEL')}</div></div></div><button class="btn small" onclick="logout()">${icon('logout')}</button></div></header><div class="page">${isAdmin?renderAdminSection():renderPersonnelSection()}</div></main></div>`}
function adminNav(){const a=[['dashboard','Overview','grid'],['personnel','Personnel','people'],['requests','Access Requests','doc'],['locations','Location Feed','map'],['messages','Messages','bell'],['archive','Archive','doc'],['studies','Studies','search'],['equipment','Equipment','shield'],['vehicles','Vehicles','grid'],['facilities','Facilities','grid'],['documents','Documents','doc'],['organizations','Organizations','people'],['events','Events','grid'],['audit','Audit Log','doc'],['security','Security','lock']];return a.map(x=>`<button class="nav-btn ${APP.section===x[0]?'active':''}" onclick="nav('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}
function personnelNav(){return [['dashboard','Overview','grid'],['profile','My Profile','people'],['messages','Messages','bell'],['location','Location Sharing','map'],['notifications','Notifications','bell']].map(x=>`<button class="nav-btn ${APP.section===x[0]?'active':''}" onclick="nav('${x[0]}')">${icon(x[2])}<span>${x[1]}</span></button>`).join('')}
function renderAdminSection(){switch(APP.section){case'personnel':return adminPersonnel();case'requests':return adminRequests();case'locations':return adminLocations();case'messages':return `<div class="page-head"><div><div class="eyebrow">MESSAGING</div><h1 class="title" style="font-size:34px">Internal Messaging</h1><div class="subtitle">Admin melihat event sistem messaging; private conversation personel tetap dilindungi oleh authorization.</div></div></div><div class="card"><div class="notice">Pesan privat personel tidak dibuka dari admin secara default. Akses administratif khusus, bila ditambahkan, harus memiliki policy dan audit trail terpisah.</div></div>${appFooter()}`;case'audit':return adminAudit();case'security':return genericAdminData('Security Center',['SESSION CONTROL','RATE LIMIT','DEVICE POLICY','AUTH EVENTS','ACCESS POLICY','ALERTS']);case'archive':return genericAdminData('Archive',['Strategic Archive','Historical Archive','Research Archive','Institutional Records']);case'studies':return genericAdminData('Studies',['Resilience Study','Defense Study','Crisis Simulation','Strategic Analysis','Regional Review']);case'equipment':return genericAdminData('Equipment',['ARX-11 Sentinel','Vektor-7 Scout','Atlas Mobile Shield','Lumen Field Sensor']);case'vehicles':return genericAdminData('Vehicles',['Meridian-12','Nusa Carrier','Sagara Utility','Arunika Field Van']);case'facilities':return genericAdminData('Facilities',['Pusat Riset Arunika','Kompleks Kajian Samudra','Laboratorium Ketahanan Kota']);case'documents':return genericAdminData('Documents',['Strategic Assessment 2041','Regional Resilience Review','Emergency Preparedness Assessment']);case'organizations':return genericAdminData('Organizations',['Lembaga Kajian Arunika','Pusat Resiliensi Nusantara','Forum Riset Cakrawala']);case'events':return genericAdminData('Historical Events',['Krisis','Perjanjian','Evakuasi','Negosiasi Strategis']);default:return adminDashboard()}}
function genericAdminData(title,items){return `<div class="page-head"><div><div class="eyebrow">DATABASE</div><h1 class="title" style="font-size:34px">${esc(title)}</h1><div class="subtitle">Dataset fiktif institusional dengan struktur yang konsisten dengan console IKSN.</div></div></div><div class="grid grid-auto">${items.concat(items).map((x,i)=>`<div class="card clickable"><div class="eyebrow">${esc(title.slice(0,3).toUpperCase())}-${String(i+1).padStart(2,'0')}</div><h3 style="font-size:13px;margin:7px 0">${esc(x)}</h3><div class="muted" style="font-size:10px">Record demonstrasi · classification ${LEVELS[i%LEVELS.length]}</div><div style="margin-top:10px">${statusChip(i%3===0?'Active':'Archived')}</div></div>`).join('')}</div>${appFooter()}`}
function adminDashboard(){return `<div class="page-head"><div><div class="eyebrow">ADMIN CONSOLE</div><h1 class="title">Institutional Overview</h1><div class="subtitle">Kontrol administratif untuk dataset fiktif, access request, lokasi yang diaktifkan user, dan audit.</div></div></div><div class="quick-grid"><div class="card stat"><div class="k">Active Personnel</div><div class="v" id="statPersonnel">—</div></div><div class="card stat"><div class="k">Pending Requests</div><div class="v" id="statRequests">—</div></div><div class="card stat"><div class="k">Location Sharing</div><div class="v" id="statLocations">—</div></div><div class="card stat"><div class="k">Audit Events</div><div class="v">${dblessAuditCount()}</div></div></div><div class="panel-grid" style="margin-top:16px"><div class="card"><div class="eyebrow">SYSTEM STATUS</div><h3 class="section-title" style="margin-top:7px">Operational</h3><div class="rule"></div><div class="grid grid-2"><div class="meta-box"><div class="k">Node</div><div class="v">HAYDAR-S/01</div></div><div class="meta-box"><div class="k">Access</div><div class="v">PRIVILEGED</div></div></div></div><div class="card"><div class="eyebrow">QUICK ACCESS</div><div class="stack" style="margin-top:12px"><button class="btn" onclick="nav('requests')">${icon('doc')} ACCESS REQUESTS</button><button class="btn" onclick="nav('locations')">${icon('map')} LOCATION FEED</button><button class="btn" onclick="nav('personnel')">${icon('people')} PERSONNEL DIRECTORY</button></div></div></div>${appFooter()}</div>`}
let _auditCount=0;function dblessAuditCount(){return _auditCount||'—'}
async function hydrateAdminStats(){try{const [p,r,l,a]=await Promise.all([api('/api/admin/personnel'),api('/api/admin/requests'),api('/api/admin/locations'),api('/api/admin/audit')]);_auditCount=a.data.audit.length;const e=id=>document.getElementById(id);if(e('statPersonnel'))e('statPersonnel').textContent=p.data.personnel.filter(x=>x.status==='Active').length;if(e('statRequests'))e('statRequests').textContent=r.data.requests.filter(x=>x.status==='PENDING').length;if(e('statLocations'))e('statLocations').textContent=l.data.locations.length}catch(e){if(APP.view==='app'&&APP.role==='ADMIN')toast(e.message,'danger')}}
function adminPersonnel(){return `<div class="page-head"><div><div class="eyebrow">DATABASE</div><h1 class="title" style="font-size:34px">Personnel</h1><div class="subtitle">Identitas server-backed; tidak ada fallback random saat login.</div></div></div><div class="card"><div class="toolbar"><input class="input grow" id="personnelSearch" placeholder="Cari nama, ID, email, divisi..." oninput="debounce(loadAdminPersonnel)"><button class="btn" onclick="loadAdminPersonnel()">${icon('refresh')} REFRESH</button></div><div id="personnelResults"></div></div>${appFooter()}`}
let searchTimer=null;function debounce(fn){clearTimeout(searchTimer);searchTimer=setTimeout(fn,250)}
async function loadAdminPersonnel(){try{const q=document.getElementById('personnelSearch')?.value||'';const r=await api('/api/admin/personnel?q='+encodeURIComponent(q));document.getElementById('personnelResults').innerHTML=r.data.personnel.map(p=>`<div class="result-card card" style="display:grid;margin-top:9px"><div class="row"><span class="k">ID</span><span class="v"><b>${esc(p.id)}</b></span></div><div class="row"><span class="k">Nama</span><span class="v">${esc(p.name)}</span></div><div class="row"><span class="k">Division</span><span class="v">${esc(p.division)}</span></div><div class="row"><span class="k">Status</span><span class="v">${statusChip(p.status)}</span></div><div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:10px"><button class="btn small" onclick="viewPersonnel('${p.id}')">VIEW</button>${p.status==='Active'?`<button class="btn small danger" onclick="personnelAction('${p.id}','terminate')">TERMINATE</button>`:''}<button class="btn small" onclick="personnelAction('${p.id}','revoke')">REVOKE</button></div></div>`).join('')||'<div class="notice">Tidak ada record.</div>'}catch(e){toast(e.message,'danger')}}
async function viewPersonnel(id){const p=(await api('/api/admin/personnel?q='+encodeURIComponent(id))).data.personnel.find(x=>x.id===id);if(!p)return;openModal(p.name,`<div class="detail-head"><div class="detail-photo">${p.photo?`<img src="${p.photo}" alt="">`:''}</div><div><div class="eyebrow">${esc(p.id)}</div><h3 style="margin:7px 0">${esc(p.name)}</h3><div class="muted" style="font-size:11px">${esc(p.codename)}</div></div></div><div class="detail-meta" style="margin-top:14px"><div class="meta-box"><div class="k">Email</div><div class="v">${esc(p.email)}</div></div><div class="meta-box"><div class="k">Clearance</div><div class="v">${levelChip(p.clearance)}</div></div><div class="meta-box"><div class="k">Division</div><div class="v">${esc(p.division)}</div></div><div class="meta-box"><div class="k">Status</div><div class="v">${statusChip(p.status)}</div></div></div>`)}
async function personnelAction(id,action){if(!confirm(`Konfirmasi ${action} untuk ${id}?`))return;try{await api(`/api/admin/personnel/${encodeURIComponent(id)}/${action}`,{method:'POST',body:JSON.stringify({reason:'Admin console action'})});toast('Action berhasil.','success');loadAdminPersonnel()}catch(e){toast(e.message,'danger')}}
function adminRequests(){return `<div class="page-head"><div><div class="eyebrow">ACCESS REVIEW</div><h1 class="title" style="font-size:34px">Access Requests</h1><div class="subtitle">Review foto, verifikasi prototype, lalu approve/reject dari server.</div></div><div class="actions"><button class="btn" onclick="loadAdminRequests()">${icon('refresh')} REFRESH</button></div></div><div class="card"><div id="requestResults"><div class="notice">Memuat data...</div></div></div>${appFooter()}`}
async function loadAdminRequests(){try{const r=await api('/api/admin/requests');APP.requests=r.data.requests;document.getElementById('requestResults').innerHTML=APP.requests.map(x=>`<div class="card" style="margin-top:9px"><div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start"><div><div class="eyebrow">${esc(x.id)}</div><h3 style="margin:7px 0;font-size:14px">${esc(x.name)}</h3><div class="muted" style="font-size:10px">${esc(x.email)} · ${esc(x.institution)}</div></div>${statusChip(x.status)}</div><div class="grid grid-3" style="margin-top:12px"><div class="meta-box"><div class="k">Position</div><div class="v">${esc(x.position)}</div></div><div class="meta-box"><div class="k">Clearance</div><div class="v">${levelChip(x.clearance)}</div></div><div class="meta-box"><div class="k">Face</div><div class="v">${x.biometricVerified?'COMPLETED':'NOT COMPLETE'}</div></div></div>${x.status==='PENDING'?`<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button class="btn small" onclick="reviewRequest('${x.id}')">REVIEW</button><button class="btn small primary" onclick="approveRequest('${x.id}')">APPROVE</button><button class="btn small danger" onclick="rejectRequest('${x.id}')">REJECT</button></div>`:''}</div>`).join('')||'<div class="notice">Tidak ada access request.</div>'}catch(e){toast(e.message,'danger')}}
function reviewRequest(id){const r=APP.requests.find(x=>x.id===id);if(!r)return;openModal('Review Access Request',`<div class="review-grid"><div class="review-photo">${r.photo?`<img src="${r.photo}" alt="Foto ${esc(r.name)}">`:'Tidak ada foto'}</div><div><div class="meta-box"><div class="k">Applicant</div><div class="v">${esc(r.name)}</div></div><div class="meta-box"><div class="k">Institution</div><div class="v">${esc(r.institution)}</div></div><div class="meta-box"><div class="k">Verification</div><div class="v">${r.biometricVerified?'COMPLETED':'NOT COMPLETE'}</div></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:15px"><button class="btn primary" onclick="closeModal();approveRequest('${r.id}')">APPROVE</button><button class="btn danger" onclick="closeModal();rejectRequest('${r.id}')">REJECT</button></div></div></div>`)}
async function approveRequest(id){try{await api('/api/admin/requests/'+encodeURIComponent(id)+'/approve',{method:'POST',body:JSON.stringify({})});toast('Pengajuan disetujui dan personnel account diperbarui.','success');loadAdminRequests()}catch(e){toast(e.message,'danger')}}
async function rejectRequest(id){const reason=prompt('Alasan penolakan:','Dokumen belum memenuhi pemeriksaan administratif');if(reason===null)return;try{await api('/api/admin/requests/'+encodeURIComponent(id)+'/reject',{method:'POST',body:JSON.stringify({reason})});toast('Pengajuan ditolak.','success');loadAdminRequests()}catch(e){toast(e.message,'danger')}}
function adminLocations(){return `<div class="page-head"><div><div class="eyebrow">LOCATION FEED</div><h1 class="title" style="font-size:34px">Personnel Location</h1><div class="subtitle">Hanya menampilkan personel yang mengaktifkan berbagi lokasi dan mengirim titik baru.</div></div><div class="actions"><button class="btn" onclick="loadAdminLocations()">${icon('refresh')} REFRESH</button></div></div><div class="radar-layout"><div class="card"><div id="radar" class="radar"><div class="radar-v"></div><div class="radar-h"></div><div class="radar-line"></div><div class="radar-core"></div></div></div><div class="card"><div class="eyebrow">RECENT LOCATION</div><div id="locationList" class="personnel-list" style="margin-top:12px"><div class="notice">Memuat...</div></div></div></div>${appFooter()}`}
async function loadAdminLocations(){try{const r=await api('/api/admin/locations');APP.locations=r.data.locations;const list=document.getElementById('locationList');if(!list)return;list.innerHTML=APP.locations.map((x,i)=>`<div class="person-card"><div class="p-avatar">${APP.personnel?.photo?`<img src="${APP.personnel.photo}" alt="">`:''}</div><div><div class="name">${esc(x.name)}</div><div class="meta">${esc(x.personnelId)} · ±${Math.round(x.accuracy)}m · ${x.ageSeconds}s</div><div class="coords">${x.latitude.toFixed(5)}, ${x.longitude.toFixed(5)}</div></div><div>${x.ageSeconds<30?statusChip('Active'):statusChip('STALE')}</div></div>`).join('')||'<div class="notice">Belum ada lokasi aktif. Personel harus mengaktifkan berbagi lokasi.</div>'}catch(e){toast(e.message,'danger')}}
function adminAudit(){return `<div class="page-head"><div><div class="eyebrow">AUDIT</div><h1 class="title" style="font-size:34px">Audit Log</h1><div class="subtitle">Event authentication, request, location, personnel action, dan messaging.</div></div></div><div class="card"><div id="auditList"><div class="notice">Memuat...</div></div></div>${appFooter()}`}
async function loadAudit(){try{const r=await api('/api/admin/audit');document.getElementById('auditList').innerHTML=r.data.audit.map(x=>`<div class="meta-box"><div style="display:flex;justify-content:space-between;gap:10px"><b style="font-size:11px">${esc(x.action)}</b>${statusChip(x.result)}</div><div class="muted" style="font-size:10px;margin-top:4px">${esc(x.timestamp)} · ${esc(x.actor)} · ${esc(x.target||'—')}</div></div>`).join('')}catch(e){toast(e.message,'danger')}}
function renderPersonnelSection(){switch(APP.section){case'profile':return personProfile();case'messages':return messagesPage();case'location':return personLocation();case'notifications':return personNotifications();default:return personDashboard()}}
function personDashboard(){return `<div class="page-head"><div><div class="eyebrow">PERSONNEL CONSOLE</div><h1 class="title">Selamat datang, ${esc(APP.personnel?.name||'Personel')}</h1><div class="subtitle">Ruang kerja terotorisasi untuk profil, pesan internal, dan kontrol berbagi lokasi.</div></div></div><div class="quick-grid"><div class="card stat"><div class="k">Personnel ID</div><div class="v" style="font-size:21px">${esc(APP.personnel?.id||'—')}</div></div><div class="card stat"><div class="k">Clearance</div><div class="v" style="font-size:21px">${esc(APP.personnel?.clearance||'—')}</div></div><div class="card stat"><div class="k">Role</div><div class="v" style="font-size:21px">${esc(APP.personnel?.role||'—')}</div></div><div class="card stat"><div class="k">Status</div><div class="v" style="font-size:21px">ACTIVE</div></div></div><div class="panel-grid" style="margin-top:16px"><div class="card"><div class="eyebrow">INTERNAL MESSAGING</div><h3 class="section-title" style="margin-top:7px">Pesan antar-personel</h3><p class="muted" style="font-size:12px;line-height:1.6">Kirim dan terima pesan dengan personel lain yang aktif.</p><button class="btn primary" onclick="nav('messages')">BUKA PESAN</button></div><div class="card"><div class="eyebrow">LOCATION SHARING</div><h3 class="section-title" style="margin-top:7px">Berbagi lokasi</h3><p class="muted" style="font-size:12px;line-height:1.6">Opsional. Admin hanya melihat titik yang Anda kirim setelah Anda mengaktifkan fitur.</p><button class="btn" onclick="nav('location')">ATUR LOKASI</button></div></div>${appFooter()}`}
function personProfile(){return `<div class="page-head"><div><div class="eyebrow">MY PROFILE</div><h1 class="title" style="font-size:34px">Profil Personel</h1></div></div><div class="card"><div class="detail-head"><div class="detail-photo">${APP.personnel?.photo?`<img src="${APP.personnel.photo}" alt="">`:''}</div><div><div class="eyebrow">${esc(APP.personnel?.id)}</div><h3 style="margin:7px 0">${esc(APP.personnel?.name)}</h3><div class="muted" style="font-size:12px">${esc(APP.personnel?.position)}</div></div></div><div class="detail-meta" style="margin-top:14px"><div class="meta-box"><div class="k">Email</div><div class="v">${esc(APP.personnel?.email)}</div></div><div class="meta-box"><div class="k">Division</div><div class="v">${esc(APP.personnel?.division)}</div></div><div class="meta-box"><div class="k">Region</div><div class="v">${esc(APP.personnel?.region)}</div></div><div class="meta-box"><div class="k">Clearance</div><div class="v">${levelChip(APP.personnel?.clearance)}</div></div></div></div>${appFooter()}`}
function personLocation(){const enabled=APP.location.enabled;return `<div class="page-head"><div><div class="eyebrow">SECURITY CENTER</div><h1 class="title" style="font-size:34px">Location Sharing</h1><div class="subtitle">Lokasi hanya dikirim saat Anda mengaktifkan fitur ini.</div></div></div><div class="card"><div class="location-consent"><div><b style="font-size:13px">Berbagi lokasi ${enabled?'aktif':'nonaktif'}</b><div class="help">${enabled?'Titik lokasi terbaru dikirim ke server saat tersedia.':'Tidak ada koordinat yang dikirim.'}</div></div><label class="switch"><input id="locSwitch" type="checkbox" ${enabled?'checked':''} onchange="toggleLocation(this.checked)"><span class="slider"></span></label></div><div id="locStatus" style="margin-top:12px">${APP.location.last?`<div class="notice success">Lokasi terakhir: ${APP.location.last.lat.toFixed(5)}, ${APP.location.last.lon.toFixed(5)} ±${Math.round(APP.location.last.accuracy)}m</div>`:'<div class="notice">Belum ada titik lokasi dari perangkat ini.</div>'}</div></div>${appFooter()}`}
async function loadLocationState(){try{const r=await api('/api/location/me');APP.location.enabled=r.data.enabled;APP.location.last=r.data.location?{lat:r.data.location.latitude,lon:r.data.location.longitude,accuracy:r.data.location.accuracy}:null}catch(e){}}
async function toggleLocation(enabled){try{await api('/api/location/toggle',{method:'POST',body:JSON.stringify({enabled})});APP.location.enabled=enabled;if(enabled)startLocation();else stopLocation();toast(enabled?'Berbagi lokasi aktif.':'Berbagi lokasi dihentikan.',enabled?'success':'info');render()}catch(e){toast(e.message,'danger')}}
function startLocation(){if(!navigator.geolocation)return toast('Browser tidak mendukung geolocation.','danger');if(!window.isSecureContext&&!['localhost','127.0.0.1'].includes(location.hostname))return toast('Lokasi memerlukan HTTPS atau localhost.','danger');if(APP.location.watchId!==null)return;APP.location.watchId=navigator.geolocation.watchPosition(sendLocation,{enableHighAccuracy:true,maximumAge:10000,timeout:15000})}
async function sendLocation(pos){const loc={lat:pos.coords.latitude,lon:pos.coords.longitude,accuracy:pos.coords.accuracy};APP.location.last=loc;try{await api('/api/location',{method:'POST',body:JSON.stringify({latitude:loc.lat,longitude:loc.lon,accuracy:loc.accuracy})});if(document.getElementById('locStatus'))document.getElementById('locStatus').innerHTML=`<div class="notice success">Lokasi terakhir: ${loc.lat.toFixed(5)}, ${loc.lon.toFixed(5)} ±${Math.round(loc.accuracy)}m</div>`}catch(e){if(!/LOCATION_NOT_ENABLED/i.test(e.message))toast(e.message,'danger')}}
function stopLocation(){if(APP.location.watchId!==null&&navigator.geolocation){navigator.geolocation.clearWatch(APP.location.watchId);APP.location.watchId=null}}
async function personNotifications(){try{const r=await api('/api/notifications');APP.notifications=r.data.notifications}catch{} }
function personNotifications(){return `<div class="page-head"><div><div class="eyebrow">NOTIFICATIONS</div><h1 class="title" style="font-size:34px">Notifikasi</h1></div></div><div class="card"><div id="notificationList"><div class="notice">Memuat...</div></div></div>${appFooter()}`}
async function loadNotifications(){try{const r=await api('/api/notifications');APP.notifications=r.data.notifications;const e=document.getElementById('notificationList');if(e)e.innerHTML=APP.notifications.map(n=>`<div class="meta-box"><div style="display:flex;justify-content:space-between;gap:10px"><b style="font-size:11px">${esc(n.title)}</b>${n.readAt?statusChip('Archived'):statusChip('NOTICE')}</div><div class="muted" style="font-size:10px;margin-top:4px">${esc(n.body)}</div></div>`).join('')||'<div class="notice">Tidak ada notifikasi.</div>'}catch(e){}}
function messagesPage(){return `<div class="page-head"><div><div class="eyebrow">MESSAGING</div><h1 class="title" style="font-size:34px">Percakapan Personel</h1><div class="subtitle">Pesan internal antar-personel yang telah disetujui.</div></div><div class="actions"><button class="btn" onclick="openCompose()">PESAN BARU</button></div></div><div class="message-shell"><aside class="thread-list" id="threadList"><div class="notice" style="margin:12px">Memuat...</div></aside><section class="chat-panel" id="chatPanel"><div class="chat-empty"><div><div class="eyebrow">INTERNAL MESSAGING</div><h3 style="margin:8px 0">Pilih percakapan</h3><p class="muted" style="font-size:12px">Pesan akan disimpan di server dan tetap ada setelah refresh.</p></div></div></section></div>${appFooter()}`}
async function loadMessagesHome(){try{const [c,t]=await Promise.all([api('/api/messages/conversations'),api('/api/messages/contacts')]);APP.conversations=c.data.conversations;APP.contacts=t.data.contacts;renderThreadList()}catch(e){toast(e.message,'danger')}}
function renderThreadList(){const el=document.getElementById('threadList');if(!el)return;el.innerHTML=APP.conversations.map(c=>`<button class="thread-item ${APP.activeConversation===c.id?'active':''}" onclick="openConversation('${c.id}')"><div class="thread-avatar">${c.other?.photo?`<img src="${c.other.photo}" alt="">`:''}</div><div class="thread-main"><div class="thread-name">${esc(c.other?.name||'Personel')}</div><div class="thread-preview">${esc(c.lastMessage||'Belum ada pesan')}</div></div><div>${c.unread?`<span class="unread-badge">${c.unread}</span>`:''}</div></button>`).join('')||'<div class="notice" style="margin:12px">Belum ada percakapan. Gunakan PESAN BARU.</div>'}
async function openConversation(id){APP.activeConversation=id;try{const r=await api('/api/messages/conversations/'+encodeURIComponent(id));APP.messages=r.data.messages;renderThreadList();renderChat(r.data.conversation)}catch(e){toast(e.message,'danger')}}
function renderChat(c){const otherId=c.memberIds.find(x=>x!==APP.personnel.id);const other=APP.contacts.find(x=>x.id===otherId)||APP.conversations.find(x=>x.id===c.id)?.other;const p=(other||{});document.getElementById('chatPanel').innerHTML=`<div class="chat-head"><button class="btn small mobile-back" onclick="document.getElementById('chatPanel').innerHTML='<div class=\'chat-empty\'><div>Pilih percakapan.</div></div>'">←</button><div class="thread-avatar">${p.photo?`<img src="${p.photo}" alt="">`:''}</div><div><div style="font-size:12px;font-weight:700">${esc(p.name||'Personel')}</div><div class="muted" style="font-size:9px">${esc(p.role||'PERSONNEL')}</div></div></div><div class="chat-messages" id="chatMessages">${APP.messages.map(m=>{const mine=m.senderId===APP.personnel.id;return `<div class="msg-row ${mine?'mine':''}"><div><div class="msg-bubble">${esc(m.body)}</div><div class="msg-meta">${new Date(m.createdAt).toLocaleString('id-ID')}</div></div></div>`}).join('')||'<div class="chat-empty"><div class="muted">Belum ada pesan.</div></div>'}</div><div class="chat-compose"><textarea id="msgInput" class="textarea" maxlength="2000" placeholder="Ketik pesan..."></textarea><button class="btn primary" onclick="sendMessage('${c.id}')">${icon('send')} KIRIM</button></div>`;document.getElementById('chatMessages').scrollTop=1e9}
async function sendMessage(convId){const input=document.getElementById('msgInput');const body=input?.value.trim();if(!body)return;const c=APP.conversations.find(x=>x.id===convId);const to=c?.other?.id;if(!to){return toast('Penerima tidak ditemukan.','danger')}try{await api('/api/messages',{method:'POST',body:JSON.stringify({toPersonnelId:to,body})});input.value='';await openConversation(convId);await loadMessagesHome()}catch(e){toast(e.message,'danger')}}
function dbConversation(id){return APP.currentConversationCache?.[id] || null}
function openCompose(){const contacts=APP.contacts.length?APP.contacts:[];openModal('Pesan Baru',`<div class="field"><label class="label">Penerima</label><select class="select" id="composeTo">${contacts.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} — ${esc(c.role)}</option>`).join('')}</select></div><div class="field"><label class="label">Pesan</label><textarea class="textarea" id="composeBody" maxlength="2000" placeholder="Ketik pesan..."></textarea></div><button class="btn primary block" onclick="sendNewMessage()">${icon('send')} KIRIM PESAN</button>`)}
async function sendNewMessage(){const to=document.getElementById('composeTo')?.value;const body=document.getElementById('composeBody')?.value.trim();if(!to||!body)return toast('Lengkapi penerima dan pesan.','danger');try{const r=await api('/api/messages',{method:'POST',body:JSON.stringify({toPersonnelId:to,body})});closeModal();await loadMessagesHome();const convId=r.data.conversationId;APP.currentConversationCache=APP.currentConversationCache||{};const rc=APP.conversations.find(x=>x.id===convId);if(rc)rc.memberIds=[APP.personnel.id,to];await openConversation(convId)}catch(e){toast(e.message,'danger')}}
async function syncMessageConversationCache(){APP.currentConversationCache={};for(const c of APP.conversations)APP.currentConversationCache[c.id]={memberIds:[APP.personnel.id,c.other?.id]}}
function appFooter(){return `<div class="footer"><div class="footer-row"><div>IKSN · FICTIONAL INSTITUTIONAL PROTOTYPE · HAYDAR-S/01</div><div class="footer-links"><button onclick="openInfo()">Informasi</button><button onclick="logout()">Keluar</button></div></div></div>`}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}clearClientTimers();APP.role=null;APP.user=null;APP.personnel=null;APP.view='logout';render();setTimeout(()=>setView('welcome'),700)}
function logoutView(){return `<div class="welcome view"><div class="welcome-panel"><div style="margin-bottom:16px">${logo(true)}</div><div class="eyebrow">SESSION CLOSED</div><div class="title">Sesi ditutup.</div><div class="muted">Kembali ke lingkungan informasi awal.</div></div></div>`}
async function hydrateSession(){try{const r=await api('/api/auth/session');APP.role=r.data.role;APP.user=r.data.user;APP.personnel=r.data.personnel;startRefresh();if(APP.role==='PERSONNEL'){await loadLocationState();if(APP.location.enabled)startLocation()}APP.view='app';APP.section='dashboard';render();}catch{render()}}
function startRefresh(){if(APP.refreshTimer)clearInterval(APP.refreshTimer);APP.refreshTimer=setInterval(()=>{api('/api/auth/session/refresh').catch(()=>{});},8*60*1000)}
function render(){stopScanOnly();const root=document.getElementById('app');if(APP.view==='welcome')root.innerHTML=welcomeView();else if(APP.view==='auth')root.innerHTML=authView();else if(APP.view==='register')root.innerHTML=registerView();else if(APP.view==='status')root.innerHTML=statusView();else if(APP.view==='adminLogin'){APP.auth.mode='admin';root.innerHTML=`<div class="auth-shell view"><aside class="auth-aside"><div>${logo()}<div class="eyebrow" style="margin-top:26px">Privileged Access</div><h2 style="font-size:28px;line-height:1.15">Administrator Gate.</h2><p class="muted" style="font-size:12px;line-height:1.7">Akses administrator hanya berasal dari kredensial server-side.</p></div><div class="muted" style="font-size:10px">PROTOTYPE ENVIRONMENT</div></aside><main class="auth-main"><div class="auth-box"><div class="auth-top"><button class="mini-link" onclick="setView('welcome')">← Kembali</button><div class="eyebrow">ADMIN PORTAL</div></div>${adminAuthBody()}</div></main></div>`;}else if(APP.view==='app')root.innerHTML=appShell();else if(APP.view==='logout')root.innerHTML=logoutView();bindAfterRender();}
function bindAfterRender(){if(APP.view==='app'){if(APP.role==='ADMIN'){if(APP.section==='personnel')loadAdminPersonnel();if(APP.section==='requests')loadAdminRequests();if(APP.section==='locations'){loadAdminLocations();setInterval(()=>{if(APP.view==='app'&&APP.section==='locations')loadAdminLocations()},15000)}if(APP.section==='audit')loadAudit();if(APP.section==='dashboard')hydrateAdminStats();}else{if(APP.section==='messages'){loadMessagesHome();if(APP.messagePoll)clearInterval(APP.messagePoll);APP.messagePoll=setInterval(()=>{if(APP.view==='app'&&APP.section==='messages')loadMessagesHome()},5000)}if(APP.section==='location')loadLocationState();if(APP.section==='notifications')loadNotifications();}}}
window.addEventListener('pagehide',()=>{stopCamera();stopLocation()});
window.addEventListener('DOMContentLoaded',()=>{hydrateSession()});
window.startAuth=startAuth;window.openInfo=openInfo;window.setView=setView;window.adminLogin=adminLogin;window.requestUserOtp=requestUserOtp;window.verifyUserOtp=verifyUserOtp;window.verifyUserCredential=verifyUserCredential;window.requestAdminOtp=requestAdminOtp;window.verifyAdminOtp=verifyAdminOtp;window.startCamera=startCamera;window.finishFace=finishFace;window.stopCamera=stopCamera;window.manualPrototypeFaceCheck=manualPrototypeFaceCheck;window.enterApp=enterApp;window.loadRequestStatus=loadRequestStatus;window.saveRegPersonal=saveRegPersonal;window.saveRegInstitution=saveRegInstitution;window.handlePhotoFile=handlePhotoFile;window.confirmRegPhoto=confirmRegPhoto;window.startRegistrationCapture=startRegistrationCapture;window.captureRegPhoto=captureRegPhoto;window.closeRegCamera=closeRegCamera;window.submitAccessRequest=submitAccessRequest;window.nav=nav;window.logout=logout;window.loadAdminPersonnel=loadAdminPersonnel;window.personnelAction=personnelAction;window.viewPersonnel=viewPersonnel;window.loadAdminRequests=loadAdminRequests;window.reviewRequest=reviewRequest;window.approveRequest=approveRequest;window.rejectRequest=rejectRequest;window.loadAdminLocations=loadAdminLocations;window.loadAudit=loadAudit;window.toggleLocation=toggleLocation;window.messagesPage=messagesPage;window.openConversation=openConversation;window.sendMessage=sendMessage;window.openCompose=openCompose;window.sendNewMessage=sendNewMessage;window.closeModal=closeModal;
